arguments.command:
cd /app && sha256sum output/Northstar_*.xlsx output/handoff.json output/board-pack.json > /tmp/before.sha && python3 - <<'E'
import csv,json
from decimal import Decimal
rows=list(csv.DictReader(open('/app/treasury/bank_export.csv')))
book={r['bank_id']:r for r in csv.DictReader(open('/app/treasury/cashbook.csv'))}
seen={};dups=[]
for r in rows:
    k=r['bank_id'].strip()
    if k in seen:
        assert seen[k]==r, f'conflicting duplicate {k}'
        if k not in dups: dups.append(k)
    else: seen[k]=r
items=[];nc=nd=Decimal(0)
for k,r in seen.items():
    amt=Decimal(r['amount'])
    reason=('other_account' if r['account']!='MAIN' else 'other_currency' if r['currency']!='USD'
        else 'not_settled' if r['status']!='settled' else 'after_cutoff' if r['posted_date']>'2025-12-31' else None)
    if reason: items.append({'bank_id':k,'classification':'excluded','reason':reason})
    elif k in book:
        assert Decimal(book[k]['cash_amount'])==amt,k
        items.append({'bank_id':k,'classification':'matched','book_id':book[k]['book_id']})
    else:
        d=amt if r['category']=='revolver' else Decimal(0); nc+=amt; nd+=d
        items.append({'bank_id':k,'classification':'adjustment','cash_adjustment':float(amt),'debt_adjustment':float(d)})
out={'cutoff':'2025-12-31','account':'MAIN','currency':'USD','items':items,'duplicate_bank_ids':dups,
 'net_cash_adjustment':float(nc),'net_debt_adjustment':float(nd),
 'corrected_opening_cash':float(30000+nc),'corrected_opening_revolver':float(30000+nd)}
json.dump(out,open('/app/output/treasury_reconciliation.json','w'),indent=2)
for i in items: print(i)
print({k:v for k,v in out.items() if k!='items'})
E
sha256sum -c /tmp/before.sha --quiet && echo "forecast deliverables unchanged"; rm -f /tmp/before.sha

